contracts/InterestRateModel.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.28;

import {ILendingPool} from "./interfaces/Interfaces.sol";

contract InterestRateModel {
    uint constant SCALE = 1e18;

    // _______State_______
    uint public baseRate; // e.g. 0.02e18 = 2% base rate
    uint public rateSlope1; // e.g. 0.08e18 = 8%
    uint public rateSlope2; // e.g. 1.00e18 = 100%
    uint public optimalUtilization; // e.g. 0.8e18 = 80%
    uint public reserveFactor; // e.g. 0.1e18 = 10%

    mapping(address => bool) public isAdmin;

    address public lendingPool;

    // _______Event_______
    event LendingPoolSet(address indexed pool);
    event AdminSet(address indexed admin, bool allowed);

    // _______Constructor_______
    constructor(
        uint _baseRate,
        uint _rateSlope1,
        uint _rateSlope2,
        uint _optimalUtilization,
        uint _reserveFactor
    ) {
        require(_optimalUtilization <= 1e18, "Invalid optimal utilization");
        require(_reserveFactor <= 1e18, "Invalid reserve factor");
        baseRate = _baseRate;
        rateSlope1 = _rateSlope1;
        rateSlope2 = _rateSlope2;
        optimalUtilization = _optimalUtilization;
        reserveFactor = _reserveFactor;
        isAdmin[msg.sender] = true;
    }

    modifier onlyAdmin() {
        require(isAdmin[msg.sender], "Not an admin");
        _;
    }

    function setLendingPool(address _lendingPool) external onlyAdmin {
        require(_lendingPool != address(0), "Invalid pool");
        require(lendingPool == address(0), "Lending pool already set");
        lendingPool = _lendingPool;
        emit LendingPoolSet(_lendingPool);
    }

    function setAdmin(address admin, bool allowed) external onlyAdmin{
        isAdmin[admin] = allowed;
        emit AdminSet(admin, allowed);
    }

    function getBorrowRate(address asset) public view returns (uint) {
        uint utilizationRate = ILendingPool(lendingPool).getUtilizationRate(asset);
        if(utilizationRate == 0) return 0;
        if(utilizationRate <= optimalUtilization){
           return baseRate + utilizationRate * rateSlope1 / SCALE;
        } else {
           return baseRate + rateSlope1 * optimalUtilization / SCALE + 
                                            rateSlope2 * (utilizationRate - optimalUtilization) / SCALE;
        }
    }

    function getDepositRate(address asset) public view returns (uint) {
        uint borrowRate = getBorrowRate(asset);
        uint utilizationRate = ILendingPool(lendingPool).getUtilizationRate(asset);
        return (borrowRate * utilizationRate * (SCALE-reserveFactor)) / (SCALE * SCALE);
    }
}

contracts/interfaces/Interfaces.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.28;

interface ILendingPool {
    function accrueInterest(address asset) external;
    function getUtilizationRate(address asset) external view returns (uint);
    function getAccountLiquidity(address user) external view returns (uint totalDepositedUSD, uint totalBorrowedUSD);
    function getUserCurrentDeposit(address user, address asset) external view returns (uint);
    function getUserCurrentBorrow(address user, address asset) external view returns (uint);
    function repayFromLiquidation(
        address borrower,
        address repayAsset,
        uint repayAmount
    ) external;
    function seizeCollateral(
        address borrower,
        address collateralAsset,
        uint seizeAmount,
        address recipient
    ) external;
}

interface IPriceRouter {
    function getPrice(address asset) external view returns (uint);
}

interface IMyOracle {
    function getPriceMyOracle(address asset) external view returns (uint);
}

interface ILiquidation {
    function isAccountLiquidatable(address user) external view returns (bool);
    function getCloseFactor() external view returns (uint);
    function calculateSeizeAmount(
        address repayAsset,
        address collateralAsset,
        uint repayAmount
    ) external view returns (uint seizeAmount);
    function liquidationThreshold() external view returns (uint);
}

interface IInterestRateModel {
    function getBorrowRate(address asset) external view returns (uint);
    function getDepositRate(address asset) external view returns (uint);
}

contracts/LendingPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {
    IERC20Metadata
} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {
    SafeERC20
} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {
    ReentrancyGuard
} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {
    IPriceRouter,
    IInterestRateModel,
    ILiquidation
} from "./interfaces/Interfaces.sol";

contract LendingPool is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    uint public constant SECONDS_PER_YEAR = 60 * 60 * 24 * 365;
    uint public constant SCALE = 1e18;

    event AdminAdded(address indexed admin);
    event AdminRemoved(address indexed admin);
    event MarketSupported(address indexed asset, address interestRateModel);
    event MarketUnsupported(address indexed asset);
    event CollateralFactorUpdated(uint newCollateralFactor);
    event Deposit(address indexed user, address indexed asset, uint amount);
    event Borrow(address indexed user, address indexed asset, uint amount);
    event Repay(address indexed user, address indexed asset, uint amount);
    event Withdraw(address indexed user, address indexed asset, uint amount);
    event CollateralSeized(
        address indexed borrower,
        address indexed collateralAsset,
        uint seizeAmount
    );
    event RepayFromLiquidation(
        address indexed borrower,
        address indexed repayAsset,
        uint repayAmount
    );
    event Accrue(
        address indexed asset,
        uint interestAccrued,
        uint depositInterestAccrued,
        uint newTotalBorrows,
        uint newBorrowIndex,
        uint newTotalDeposits,
        uint newDepositIndex
    );

    struct Market {
        bool isSupported;
        uint totalDeposits;
        uint totalBorrows;
        uint borrowIndex;
        uint depositIndex;
        uint lastUpdateTimestamp;
        address interestRateModel;
    }

    struct Balance {
        uint deposited;
        uint borrowed;
        uint borrowIndexSnapShot;
        uint depositIndexSnapShot;
    }

    mapping(address => Market) public markets; // asset => Market
    address[] public allMarkets; // list of all supported assets
    mapping(address => bool) public marketExists; // asset => exists
    mapping(address => mapping(address => Balance)) public userBalances; // user => asset => Balance
    mapping(address => address[]) public userMarkets; // user => list of assets
    mapping(address => mapping(address => bool)) public userMarketExists; // user => asset => exists

    uint public collateralFactor; // 18 decimals

    address public liquidation;
    address public priceRouter;

    constructor(
        address _liquidation,
        address _priceRouter,
        uint _collateralFactor,
        address _admin
    ) {
        require(_admin != address(0), "Invalid admin address");
        liquidation = _liquidation;
        priceRouter = _priceRouter;
        collateralFactor = _collateralFactor;
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, _admin);
    }

    modifier onlyLiquidation() {
        require(msg.sender == liquidation, "Not liquidation contract");
        _;
    }

    modifier onlySupportedMarket(address asset) {
        require(markets[asset].isSupported, "Market not supported");
        _;
    }

    modifier amountGreaterThanZero(uint amount) {
        require(amount > 0, "Amount must be greater than zero");
        _;
    }

    /// Config functions
    function setAdmin(
        address admin,
        bool status
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (status) {
            _grantRole(DEFAULT_ADMIN_ROLE, admin);
            emit AdminAdded(admin);
        } else {
            _revokeRole(DEFAULT_ADMIN_ROLE, admin);
            emit AdminRemoved(admin);
        }
    }

    function isAdmin(address admin) external view returns (bool) {
        return hasRole(DEFAULT_ADMIN_ROLE, admin);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function grantPauserRole(address pauser) external onlyRole(PAUSER_ROLE) {
        _grantRole(PAUSER_ROLE, pauser);
    }

    function revokePauserRole(address pauser) external onlyRole(PAUSER_ROLE) {
        _revokeRole(PAUSER_ROLE, pauser);
    }

    function supportMarket(
        address asset,
        address interestRateModel
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (marketExists[asset]) {
            markets[asset].isSupported = true;
            markets[asset].interestRateModel = interestRateModel;
            emit MarketSupported(asset, interestRateModel);
            return;
        } else {
            markets[asset] = Market({
                isSupported: true,
                totalDeposits: 0,
                totalBorrows: 0,
                borrowIndex: SCALE,
                depositIndex: SCALE,
                lastUpdateTimestamp: block.timestamp,
                interestRateModel: interestRateModel
            });
            allMarkets.push(asset);
            marketExists[asset] = true;
            emit MarketSupported(asset, interestRateModel);
        }
    }

    function unsupportMarket(
        address asset
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        markets[asset].isSupported = false;
        emit MarketUnsupported(asset);
    }

    function setPriceRouter(
        address _priceRouter
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        priceRouter = _priceRouter;
    }

    function setLiquidation(
        address _liquidation
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        liquidation = _liquidation;
    }

    function setCollateralParams(
        uint _collateralFactor
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        collateralFactor = _collateralFactor;
        emit CollateralFactorUpdated(_collateralFactor);
    }

    /// Interest functions
    function getUtilizationRate(address asset) public view returns (uint) {
        Market memory market = markets[asset];
        if (market.totalDeposits == 0) return 0;
        return (market.totalBorrows * SCALE) / market.totalDeposits; // 18 decimals
    }

    function accrueInterest(address asset) public whenNotPaused {
        Market storage m = markets[asset];
        if (!m.isSupported) return;

        uint timeElapsed = block.timestamp - m.lastUpdateTimestamp;
        if (timeElapsed == 0) return;

        IInterestRateModel i = IInterestRateModel(m.interestRateModel);
        uint borrowRate = i.getBorrowRate(asset);
        uint depositRate = i.getDepositRate(asset);

        uint interestAccrued = (m.totalBorrows * borrowRate * timeElapsed) /
            SECONDS_PER_YEAR /
            SCALE;
        m.totalBorrows += interestAccrued;
        uint borrowIndexIncrease = (m.borrowIndex * borrowRate * timeElapsed) /
            SECONDS_PER_YEAR /
            SCALE;
        m.borrowIndex += borrowIndexIncrease;

        uint depositInterestAccrued = (m.totalDeposits *
            depositRate *
            timeElapsed) /
            SECONDS_PER_YEAR /
            SCALE;
        m.totalDeposits += depositInterestAccrued;
        uint depositIndexIncrease = (m.depositIndex *
            depositRate *
            timeElapsed) /
            SECONDS_PER_YEAR /
            SCALE;
        m.depositIndex += depositIndexIncrease;

        m.lastUpdateTimestamp = block.timestamp;
        emit Accrue(
            asset,
            interestAccrued,
            depositInterestAccrued,
            m.totalBorrows,
            m.borrowIndex,
            m.totalDeposits,
            m.depositIndex
        );
    }

    /// Utility - compute user's current balances
    function _currentUserDeposit(
        address user,
        address asset
    ) internal view returns (uint) {
        Balance memory b = userBalances[user][asset];
        Market memory m = markets[asset];
        if (b.deposited == 0) return 0;
        if (b.depositIndexSnapShot == 0) return b.deposited;
        return (b.deposited * m.depositIndex) / b.depositIndexSnapShot;
    }

    function _currentUserBorrow(
        address user,
        address asset
    ) internal view returns (uint) {
        Balance memory b = userBalances[user][asset];
        Market memory m = markets[asset];
        if (b.borrowed == 0) return 0;
        if (b.borrowIndexSnapShot == 0) return b.borrowed;
        return (b.borrowed * m.borrowIndex) / b.borrowIndexSnapShot;
    }

    function getAccountLiquidity(
        address user
    ) public view returns (uint totalDepositedUSD, uint totalBorrowedUSD) {
        IPriceRouter pr = IPriceRouter(priceRouter);
        address[] memory assets = userMarkets[user];
        for (uint i = 0; i < assets.length; i++) {
            address asset = assets[i];
            uint currentDeposit = _currentUserDeposit(user, asset);
            uint currentBorrow = _currentUserBorrow(user, asset);
            uint assetPrice = pr.getPrice(asset);
            uint decimals = IERC20Metadata(asset).decimals();
            // Normalize to 18 decimals: (18 decimals price * token decimals) * 10^(18 - token decimals) / 10^18
            totalDepositedUSD +=
                (assetPrice * currentDeposit) /
                (10 ** decimals);
            totalBorrowedUSD += (assetPrice * currentBorrow) / (10 ** decimals);
        }
        return (totalDepositedUSD, totalBorrowedUSD);
    }

    /// Internal helper for withdraw function
    function _maxWithdrawable(
        address user,
        address asset
    ) internal view returns (uint) {
        (uint totalDepositedUSD, uint totalBorrowedUSD) = getAccountLiquidity(
            user
        );
        uint assetPrice = IPriceRouter(priceRouter).getPrice(asset);
        uint decimals = IERC20Metadata(asset).decimals();
        uint requiredCollateralUSD = (totalBorrowedUSD * SCALE) /
            collateralFactor;
        uint maxAmountUSDWithdrawable;
        if (totalDepositedUSD > requiredCollateralUSD) {
            maxAmountUSDWithdrawable =
                totalDepositedUSD -
                requiredCollateralUSD;
        } else {
            maxAmountUSDWithdrawable = 0;
        }
        uint maxAmountTokenWithdrawable = (maxAmountUSDWithdrawable *
            (10 ** decimals)) / assetPrice; // in token decimals
        return maxAmountTokenWithdrawable;
    }

    /// View helpers
    function getUserCurrentDeposit(
        address user,
        address asset
    ) external view returns (uint) {
        return _currentUserDeposit(user, asset);
    }

    function getUserCurrentBorrow(
        address user,
        address asset
    ) external view returns (uint) {
        return _currentUserBorrow(user, asset);
    }

    /// Core Logic: deposit, borrow, repay, withdraw
    function deposit(
        address asset,
        uint amount
    )
        external
        nonReentrant
        whenNotPaused
        onlySupportedMarket(asset)
        amountGreaterThanZero(amount)
    {
        accrueInterest(asset);
        IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);
        Market storage m = markets[asset];
        Balance storage b = userBalances[msg.sender][asset];
        // Update userBalances and totalDeposits
        uint currentBalance = _currentUserDeposit(msg.sender, asset);
        b.deposited = amount + currentBalance;
        b.depositIndexSnapShot = m.depositIndex;
        m.totalDeposits += amount;
        if (!userMarketExists[msg.sender][asset]) {
            userMarkets[msg.sender].push(asset);
            userMarketExists[msg.sender][asset] = true;
        }
        emit Deposit(msg.sender, asset, amount);
    }

    function borrow(
        address asset,
        uint amount
    )
        external
        nonReentrant
        whenNotPaused
        onlySupportedMarket(asset)
        amountGreaterThanZero(amount)
    {
        accrueInterest(asset);
        Market storage m = markets[asset];
        Balance storage b = userBalances[msg.sender][asset];
        // Calculate total collateral and ensure user can borrow
        (uint totalDepositedUSD, uint totalBorrowedUSD) = getAccountLiquidity(
            msg.sender
        );
        uint assetPrice = IPriceRouter(priceRouter).getPrice(asset);
        uint decimals = IERC20Metadata(asset).decimals();
        uint amountUSD = (assetPrice * amount * (10 ** (18 - decimals))) /
            SCALE;
        require(
            (totalDepositedUSD * collateralFactor) / SCALE >=
                (totalBorrowedUSD + amountUSD),
            "Insufficient collateral"
        );
        // Update userBalances and totalBorrows
        uint currentBorrow = _currentUserBorrow(msg.sender, asset);
        b.borrowed = amount + currentBorrow;
        b.borrowIndexSnapShot = m.borrowIndex;
        m.totalBorrows += amount;
        IERC20(asset).safeTransfer(msg.sender, amount);
        emit Borrow(msg.sender, asset, amount);
    }

    function repay(
        address asset,
        uint amount
    )
        external
        nonReentrant
        whenNotPaused
        onlySupportedMarket(asset)
        amountGreaterThanZero(amount)
    {
        // Repay logic
        accrueInterest(asset);
        Market storage m = markets[asset];
        Balance storage b = userBalances[msg.sender][asset];
        // Update userBalances and totalBorrows
        uint currentBorrow = _currentUserBorrow(msg.sender, asset);
        require(currentBorrow > 0, "No borrow left");
        uint payAmount = amount;
        if (payAmount > currentBorrow) {
            payAmount = currentBorrow;
        }
        IERC20(asset).safeTransferFrom(msg.sender, address(this), payAmount);
        uint newBorrow = currentBorrow - payAmount;
        if (newBorrow == 0) {
            b.borrowed = 0;
            b.borrowIndexSnapShot = 0;
        } else {
            b.borrowed = newBorrow;
            b.borrowIndexSnapShot = m.borrowIndex;
        }
        m.totalBorrows -= payAmount;
        emit Repay(msg.sender, asset, payAmount);
    }

    function withdraw(
        address asset,
        uint amount // in asset decimals
    )
        external
        nonReentrant
        whenNotPaused
        onlySupportedMarket(asset)
        amountGreaterThanZero(amount)
    {
        accrueInterest(asset);
        Market storage m = markets[asset];
        Balance storage b = userBalances[msg.sender][asset];
        // Check user's deposit balance
        uint currentDeposit = _currentUserDeposit(msg.sender, asset);
        // Check if user has sufficient collateral after withdrawal
        uint maxAmountTokenWithdrawable = _maxWithdrawable(msg.sender, asset);
        uint actualAmount = amount;
        if (actualAmount > maxAmountTokenWithdrawable) {
            actualAmount = maxAmountTokenWithdrawable;
        }
        if (actualAmount > currentDeposit) {
            actualAmount = currentDeposit;
        }
        // Update userBalances and totalDeposits
        uint newDeposit = currentDeposit - actualAmount;
        if (newDeposit == 0) {
            b.deposited = 0;
            b.depositIndexSnapShot = 0;
        } else {
            b.deposited = newDeposit;
            b.depositIndexSnapShot = m.depositIndex;
        }
        m.totalDeposits -= actualAmount;
        IERC20(asset).safeTransfer(msg.sender, actualAmount);
        emit Withdraw(msg.sender, asset, actualAmount);
    }

    /// Liquidation hooks (only callable by Liquidation contract)
    function seizeCollateral(
        address borrower,
        address collateralAsset,
        uint seizeAmount,
        address recipient
    )
        external
        nonReentrant
        whenNotPaused
        onlyLiquidation
        amountGreaterThanZero(seizeAmount)
    {
        accrueInterest(collateralAsset);
        Balance storage borrowerBalance = userBalances[borrower][
            collateralAsset
        ];
        Market storage m = markets[collateralAsset];
        uint currentBorrowerDeposit = _currentUserDeposit(
            borrower,
            collateralAsset
        );
        require(currentBorrowerDeposit >= seizeAmount, "Not enough collateral");
        // Update borrower balances
        uint newDeposit = currentBorrowerDeposit - seizeAmount;
        if (newDeposit == 0) {
            borrowerBalance.deposited = 0;
            borrowerBalance.depositIndexSnapShot = 0;
        } else {
            borrowerBalance.deposited = newDeposit;
            borrowerBalance.depositIndexSnapShot = m.depositIndex;
        }
        m.totalDeposits -= seizeAmount;

        IERC20(collateralAsset).safeTransfer(recipient, seizeAmount);
        emit CollateralSeized(borrower, collateralAsset, seizeAmount);
    }

    function repayFromLiquidation(
        address borrower,
        address repayAsset,
        uint repayAmount
    )
        external
        nonReentrant
        whenNotPaused
        onlyLiquidation
        amountGreaterThanZero(repayAmount)
    {
        accrueInterest(repayAsset);
        Market storage m = markets[repayAsset];
        Balance storage b = userBalances[borrower][repayAsset];
        // Update borrower balances
        uint currentBorrow = _currentUserBorrow(borrower, repayAsset);

        // repayAmount should not exceed currentBorrow: checked in Liquidation contract
        uint newBorrow = currentBorrow - repayAmount;
        if (newBorrow == 0) {
            b.borrowed = 0;
            b.borrowIndexSnapShot = 0;
        } else {
            b.borrowed = newBorrow;
            b.borrowIndexSnapShot = m.borrowIndex;
        }
        m.totalBorrows -= repayAmount;

        emit RepayFromLiquidation(borrower, repayAsset, repayAmount);
    }

    /// Internal helpes for preview
    function _previewMarketAfterAccrual(
        address asset
    ) internal view returns (Market memory m) {
        m = markets[asset];
        require(m.isSupported, "Market not supported");

        uint timeElapsed = block.timestamp - m.lastUpdateTimestamp;
        require(timeElapsed > 0, "No time elapsed");

        IInterestRateModel i = IInterestRateModel(m.interestRateModel);
        uint borrowRate = i.getBorrowRate(asset);
        uint depositRate = i.getDepositRate(asset);

        uint interestAccrued = (m.totalBorrows * borrowRate * timeElapsed) /
            SECONDS_PER_YEAR /
            SCALE;
        m.totalBorrows += interestAccrued;
        uint borrowIndexIncrease = (m.borrowIndex * borrowRate * timeElapsed) /
            SECONDS_PER_YEAR /
            SCALE;
        m.borrowIndex += borrowIndexIncrease;

        uint depositInterestAccrued = (m.totalDeposits *
            depositRate *
            timeElapsed) /
            SECONDS_PER_YEAR /
            SCALE;
        m.totalDeposits += depositInterestAccrued;
        uint depositIndexIncrease = (m.depositIndex *
            depositRate *
            timeElapsed) /
            SECONDS_PER_YEAR /
            SCALE;
        m.depositIndex += depositIndexIncrease;

        m.lastUpdateTimestamp = block.timestamp;
    }

    function _previewUserDeposit(
        address user,
        address asset,
        Market memory m
    ) internal view returns (uint) {
        Balance memory b = userBalances[user][asset];
        if (b.deposited == 0) return 0;
        if (b.depositIndexSnapShot == 0) return b.deposited;
        return (b.deposited * m.depositIndex) / b.depositIndexSnapShot;
    }

    function _previewUserBorrow(
        address user,
        address asset,
        Market memory m
    ) internal view returns (uint) {
        Balance memory b = userBalances[user][asset];
        if (b.borrowed == 0) return 0;
        if (b.borrowIndexSnapShot == 0) return b.borrowed;
        return (b.borrowed * m.borrowIndex) / b.borrowIndexSnapShot;
    }

    function _previewAccountLiquidity(
        address user
    ) internal view returns (uint totalDepositedUSD, uint totalBorrowedUSD) {
        IPriceRouter pr = IPriceRouter(priceRouter);
        address[] memory assets = userMarkets[user];
        for (uint i = 0; i < assets.length; i++) {
            address asset = assets[i];
            Market memory m = _previewMarketAfterAccrual(asset);
            uint currentDeposit = _previewUserDeposit(user, asset, m);
            uint currentBorrow = _previewUserBorrow(user, asset, m);
            uint assetPrice = pr.getPrice(asset);
            uint decimals = IERC20Metadata(asset).decimals();
            // Normalize to 18 decimals: (18 decimals price * token decimals) * 10^(18 - token decimals) / 10^18
            totalDepositedUSD +=
                (assetPrice * currentDeposit) /
                (10 ** decimals);
            totalBorrowedUSD += (assetPrice * currentBorrow) / (10 ** decimals);
        }
        return (totalDepositedUSD, totalBorrowedUSD);
    }

    /// Helpers for frontend
    function getAllMarkets() external view returns (address[] memory) {
        return allMarkets;
    }

    /**
     * @notice Returns market information for a given asset.
     * @param asset The address of the asset to query.
     * @return totalDeposits The total amount deposited in the market.
     * @return totalBorrows The total amount borrowed from the market.
     * @return depositRate The current deposit interest rate for the asset.
     * @return borrowRate The current borrow interest rate for the asset.
     * @return utilizationRate The current utilization rate of the market.
     */
    function getMarketInfo(
        address asset
    )
        external
        view
        returns (
            uint totalDeposits,
            uint totalBorrows,
            uint depositRate,
            uint borrowRate,
            uint utilizationRate
        )
    {
        Market memory m = markets[asset];
        require(m.isSupported, "Market not supported");
        totalDeposits = m.totalDeposits;
        totalBorrows = m.totalBorrows;
        utilizationRate = getUtilizationRate(asset);
        borrowRate = IInterestRateModel(m.interestRateModel).getBorrowRate(
            asset
        );
        depositRate = IInterestRateModel(m.interestRateModel).getDepositRate(
            asset
        );
    }

    function getUserInfo(
        address user
    )
        external
        view
        returns (
            address[] memory assets,
            uint[] memory deposited,
            uint[] memory borrowed,
            uint totalDeposited,
            uint totalBorrowedUSD,
            uint healthFactor // 18 decimals
        )
    {
        assets = userMarkets[user];
        uint len = assets.length;
        deposited = new uint[](len);
        borrowed = new uint[](len);
        for (uint i = 0; i < len; i++) {
            address asset = assets[i];
            Market memory m = _previewMarketAfterAccrual(asset);
            deposited[i] = _previewUserDeposit(user, asset, m);
            borrowed[i] = _previewUserBorrow(user, asset, m);
        }
        (totalDeposited, totalBorrowedUSD) = _previewAccountLiquidity(user);
        if (totalBorrowedUSD == 0) {
            healthFactor = type(uint).max;
        } else {
            uint liquidationThreshold = ILiquidation(liquidation)
                .liquidationThreshold();
            healthFactor =
                (totalDeposited * liquidationThreshold) /
                totalBorrowedUSD;
        }
    }

    function preViewBorrow(
        address user,
        address asset,
        uint amount
    )
        external
        view
        returns (
            uint totalDepositedUSD,
            uint totalBorrowedUSD,
            uint newBorrowUSD,
            uint newHealthFactor
        )
    {
        require(markets[asset].isSupported, "Market not supported");
        require(amount > 0, "Amount must be greater than zero");
        (totalDepositedUSD, totalBorrowedUSD) = _previewAccountLiquidity(user);
        uint assetPrice = IPriceRouter(priceRouter).getPrice(asset);
        uint decimals = IERC20Metadata(asset).decimals();
        uint amountUSD = (assetPrice * amount * (10 ** (18 - decimals))) /
            SCALE;
        newBorrowUSD = totalBorrowedUSD + amountUSD;
        if (newBorrowUSD == 0) {
            newHealthFactor = type(uint).max;
        } else {
            uint liquidationThreshold = ILiquidation(liquidation)
                .liquidationThreshold();
            newHealthFactor =
                (totalDepositedUSD * liquidationThreshold) /
                newBorrowUSD;
        }
    }

    function preViewWithdraw(
        address user,
        address asset,
        uint amount
    )
        external
        view
        returns (
            uint totalDepositedUSD,
            uint totalBorrowedUSD,
            uint newDepositedUSD,
            uint newHealthFactor
        )
    {
        require(markets[asset].isSupported, "Market not supported");
        require(amount > 0, "Amount must be greater than zero");
        (totalDepositedUSD, totalBorrowedUSD) = _previewAccountLiquidity(user);
        uint assetPrice = IPriceRouter(priceRouter).getPrice(asset);
        uint decimals = IERC20Metadata(asset).decimals();
        uint amountUSD = (assetPrice * amount * (10 ** (18 - decimals))) /
            SCALE;
        newDepositedUSD = totalDepositedUSD > amountUSD
            ? totalDepositedUSD - amountUSD
            : 0;
        if (totalBorrowedUSD == 0) {
            newHealthFactor = type(uint).max;
        } else {
            uint liquidationThreshold = ILiquidation(liquidation)
                .liquidationThreshold();
            newHealthFactor =
                (newDepositedUSD * liquidationThreshold) /
                totalBorrowedUSD;
        }
    }

    function preViewRepay(
        address user,
        address asset,
        uint amount
    ) external view returns (uint totalBorrowedUSD, uint newBorrowedUSD) {
        require(markets[asset].isSupported, "Market not supported");
        require(amount > 0, "Amount must be greater than zero");
        (, totalBorrowedUSD) = _previewAccountLiquidity(user);
        uint assetPrice = IPriceRouter(priceRouter).getPrice(asset);
        uint decimals = IERC20Metadata(asset).decimals();
        uint amountUSD = (assetPrice * amount * (10 ** (18 - decimals))) /
            SCALE;
        newBorrowedUSD = totalBorrowedUSD > amountUSD
            ? totalBorrowedUSD - amountUSD
            : 0;
    }

    function preViewDeposit(
        address user,
        address asset,
        uint amount
    ) external view returns (uint totalDepositedUSD, uint newDepositedUSD) {
        require(markets[asset].isSupported, "Market not supported");
        require(amount > 0, "Amount must be greater than zero");
        (totalDepositedUSD, ) = _previewAccountLiquidity(user);
        uint assetPrice = IPriceRouter(priceRouter).getPrice(asset);
        uint decimals = IERC20Metadata(asset).decimals();
        uint amountUSD = (assetPrice * amount * (10 ** (18 - decimals))) /
            SCALE;
        newDepositedUSD = totalDepositedUSD + amountUSD;
    }

    function getMaxRepayAmount(
        address borrower,
        address repayAsset
    ) external view returns (uint) {
        require(markets[repayAsset].isSupported, "Market not supported");
        Market memory m = _previewMarketAfterAccrual(repayAsset);
        uint currentBorrow = _previewUserBorrow(borrower, repayAsset, m);
        return currentBorrow;
    }

    function getMaxWithdrawAmount(
        address user,
        address asset
    ) external view returns (uint) {
        require(markets[asset].isSupported, "Market not supported");
        (
            uint totalDepositedUSD,
            uint totalBorrowedUSD
        ) = _previewAccountLiquidity(user);

        Market memory m = _previewMarketAfterAccrual(asset);

        uint assetPrice = IPriceRouter(priceRouter).getPrice(asset);
        uint decimals = IERC20Metadata(asset).decimals();
        // Guarded collateral math to avoid underflow:
        // requiredCollateralUSD = totalBorrowedUSD * SCALE / collateralFactor
        // maxUSD = max(totalDepositedUSD - requiredCollateralUSD, 0)
        uint requiredCollateralUSD = (totalBorrowedUSD * SCALE) /
            collateralFactor;
        uint maxAmountUSDWithdrawable = 0;
        if (totalDepositedUSD > requiredCollateralUSD) {
            maxAmountUSDWithdrawable =
                totalDepositedUSD -
                requiredCollateralUSD;
        }
        // Convert USD cap to token amount (token decimals)
        uint maxAmountTokenWithdrawable = (maxAmountUSDWithdrawable *
            (10 ** decimals)) / assetPrice; // in token decimals
        uint currentDeposit = _previewUserDeposit(user, asset, m);
        if (maxAmountTokenWithdrawable > currentDeposit) {
            return currentDeposit;
        } else {
            return maxAmountTokenWithdrawable;
        }
    }
}

contracts/Liquidation.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {
    IERC20Metadata
} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {
    SafeERC20
} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {
    ReentrancyGuard
} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {IPriceRouter, ILendingPool} from "./interfaces/Interfaces.sol";

contract Liquidation is ReentrancyGuard, AccessControl {
    using SafeERC20 for IERC20;

    // Liquidation contract code goes here
    uint public constant SCALE = 1e18;

    event LiquidationParamsUpdated(
        uint liquidationThreshold,
        uint closeFactor,
        uint liquidationIncentive
    );
    event LiquidationExecuted(
        address indexed liquidator,
        address indexed borrower,
        address repayAsset,
        address collateralAsset,
        uint repayAmount,
        uint seizeAmount
    );

    uint public liquidationThreshold; // 18 decimal
    uint public closeFactor; // 18 decimal
    uint public liquidationIncentive; // 18 decimal

    address public priceRouter;
    address public lendingPool;

    constructor(
        address _priceRouter,
        address _lendingPool,
        uint _liquidationThreshold,
        uint _closeFactor,
        uint _liquidationIncentive
    ) {
        priceRouter = _priceRouter;
        lendingPool = _lendingPool;
        liquidationThreshold = _liquidationThreshold;
        closeFactor = _closeFactor;
        liquidationIncentive = _liquidationIncentive;
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    /// Config functions
    function setAdmin(
        address admin,
        bool status
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (status) {
            _grantRole(DEFAULT_ADMIN_ROLE, admin);
        } else {
            _revokeRole(DEFAULT_ADMIN_ROLE, admin);
        }
    }

    function setPriceRouter(
        address _priceRouter
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        priceRouter = _priceRouter;
    }

    function setLendingPool(
        address _lendingPool
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        lendingPool = _lendingPool;
    }

    function setLiquidateParams(
        uint _liquidationThreshold,
        uint _closeFactor,
        uint _liquidationIncentive
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        liquidationThreshold = _liquidationThreshold;
        closeFactor = _closeFactor;
        liquidationIncentive = _liquidationIncentive;
        emit LiquidationParamsUpdated(
            _liquidationThreshold,
            _closeFactor,
            _liquidationIncentive
        );
    }

    /// Helpers
    function isAccountLiquidatable(address user) public view returns (bool) {
        (uint totalDepositedUSD, uint totalBorrowedUSD) = ILendingPool(
            lendingPool
        ).getAccountLiquidity(user);
        if (totalDepositedUSD == 0) {
            return false;
        }
        if (
            (totalBorrowedUSD * SCALE) / totalDepositedUSD >=
            liquidationThreshold
        ) {
            return true;
        }
        return false;
    }

    function getCloseFactor() external view returns (uint) {
        return closeFactor;
    }

    /// Core logic
    function calculateSeizeAmount(
        address repayAsset,
        address collateralAsset,
        uint repayAmount
    ) public view returns (uint seizeAmount) {
        IPriceRouter pr = IPriceRouter(priceRouter);
        uint priceBorrowed = pr.getPrice(repayAsset);
        uint priceCollateral = pr.getPrice(collateralAsset);
        require(
            priceBorrowed > 0 && priceCollateral > 0,
            "Invalid asset price"
        );
        seizeAmount =
            (repayAmount * (SCALE + liquidationIncentive) * priceBorrowed) /
            (priceCollateral * SCALE);
    }

    function liquidate(
        address borrower,
        address liquidator,
        address repayAsset,
        address collateralAsset,
        uint repayAmount
    ) external nonReentrant {
        require(
            borrower != address(0) && liquidator != address(0),
            "Zero address"
        );
        require(repayAmount > 0, "Repay amount must be greater than zero");
        require(
            lendingPool != address(0) && priceRouter != address(0),
            "LendingPool or PriceRouter not set"
        );

        ILendingPool lendingPoolContract = ILendingPool(lendingPool);
        lendingPoolContract.accrueInterest(repayAsset);
        lendingPoolContract.accrueInterest(collateralAsset);

        require(isAccountLiquidatable(borrower), "Account is not liquidatable");
        uint currentBorrow = lendingPoolContract.getUserCurrentBorrow(
            borrower,
            repayAsset
        );
        uint maxRepayAmount = (currentBorrow *
            (10 ** (18 - IERC20Metadata(repayAsset).decimals())) *
            closeFactor) / SCALE; // convert to 18 decimals
        uint actualRepayAmount = repayAmount > maxRepayAmount
            ? maxRepayAmount
            : repayAmount;
        // Transfer repayAmount of repayAsset from liquidator to LendingPool
        IERC20(repayAsset).safeTransferFrom(
            liquidator,
            lendingPool,
            actualRepayAmount
        );
        // Update borrower's borrow balance in LendingPool
        lendingPoolContract.repayFromLiquidation(
            borrower,
            repayAsset,
            actualRepayAmount
        );
        // Calculate seize amount
        uint seizeAmountIn18decimals = calculateSeizeAmount(
            repayAsset,
            collateralAsset,
            actualRepayAmount
        );
        uint seizeAmount = (seizeAmountIn18decimals *
            (10 ** IERC20Metadata(collateralAsset).decimals())) / SCALE; // convert back to collateral asset decimals
        // Check borrower's collateral balance
        uint borrowerDeposit = lendingPoolContract.getUserCurrentDeposit(
            borrower,
            collateralAsset
        );
        if (seizeAmount > borrowerDeposit) {
            seizeAmount = borrowerDeposit;
        }
        require(seizeAmount > 0, "Seize amount is zero");
        // Update borrower's collateral balance in LendingPool
        lendingPoolContract.seizeCollateral(
            borrower,
            collateralAsset,
            seizeAmount,
            liquidator
        );

        emit LiquidationExecuted(
            liquidator,
            borrower,
            repayAsset,
            collateralAsset,
            repayAmount,
            seizeAmount
        );
    }
}

